void dei_system_convenience_alert( void )
{	
	dei_led_flash( DEI_LED_HHU_CONV_ALERT , TRUE);
	
	dei_sc_set_alert_event( 0x01 );
	notify_send( NOTIFY_CONVENIENCE_ALERT  ) ; 	
}


